package com.example.woshield;

import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;

/**
 * Transparent and explainable outcome generated by the Safety Intelligence Engine.
 * Records the triggered rule, applied measurements, plain-language explanation,
 * and any resulting safety check action taken.
 */
public class SafetyDecision implements Serializable {

    // Decision Outcomes
    public static final String OUTCOME_NO_ACTION = "NO_ACTION";
    public static final String OUTCOME_MONITORING_UNCERTAIN = "MONITORING_UNCERTAIN";
    public static final String OUTCOME_SAFETY_CHECK_RECOMMENDED = "SAFETY_CHECK_RECOMMENDED";
    public static final String OUTCOME_ASSISTANCE_REQUESTED = "ASSISTANCE_REQUESTED";
    public static final String OUTCOME_EMERGENCY_ACTIVE = "EMERGENCY_ACTIVE";

    // Triggering Rule Identifiers
    public static final String RULE_EXPLICIT_SOS = "RULE_EXPLICIT_SOS";
    public static final String RULE_MISSED_CHECKIN = "RULE_MISSED_CHECKIN";
    public static final String RULE_EXPLICIT_ASSISTANCE = "RULE_EXPLICIT_ASSISTANCE";
    public static final String RULE_STALE_LOCATION = "RULE_STALE_LOCATION";
    public static final String RULE_POOR_ACCURACY = "RULE_POOR_ACCURACY";
    public static final String RULE_SUSTAINED_DEVIATION = "RULE_SUSTAINED_DEVIATION";
    public static final String RULE_UNEXPECTED_DELAY = "RULE_UNEXPECTED_DELAY";
    public static final String RULE_DESTINATION_REACHED = "RULE_DESTINATION_REACHED";
    public static final String RULE_NORMAL_TRANSIT = "RULE_NORMAL_TRANSIT";
    public static final String RULE_DEDUPLICATED = "RULE_DEDUPLICATED";

    // Action Taken Constants
    public static final String ACTION_NONE = "NONE";
    public static final String ACTION_CHECKIN_DISPATCHED = "CHECKIN_DISPATCHED";
    public static final String ACTION_SOS_ACTIVE = "SOS_ACTIVE";
    public static final String ACTION_ASSISTANCE_ACTIVE = "ASSISTANCE_ACTIVE";

    private String decisionId;
    private String ownerUid;
    private String routineId;
    private long timestamp;
    private String outcome;
    private String triggeringRule;
    private String explanation;
    private String uncertaintyReason;
    private List<SafetySignal> signals;
    private boolean dismissed;
    private String actionTaken;
    private boolean deduplicated;

    public SafetyDecision() {
        this.timestamp = System.currentTimeMillis();
        this.outcome = OUTCOME_NO_ACTION;
        this.triggeringRule = RULE_NORMAL_TRANSIT;
        this.explanation = "Normal monitoring.";
        this.signals = new ArrayList<>();
        this.dismissed = false;
        this.actionTaken = ACTION_NONE;
        this.deduplicated = false;
    }

    public SafetyDecision(String decisionId, String ownerUid, String routineId,
                          String outcome, String triggeringRule, String explanation) {
        this.decisionId = decisionId;
        this.ownerUid = ownerUid;
        this.routineId = routineId;
        this.timestamp = System.currentTimeMillis();
        this.outcome = outcome;
        this.triggeringRule = triggeringRule;
        this.explanation = explanation;
        this.signals = new ArrayList<>();
        this.dismissed = false;
        this.actionTaken = ACTION_NONE;
        this.deduplicated = false;
    }

    public String getDecisionId() { return decisionId; }
    public void setDecisionId(String decisionId) { this.decisionId = decisionId; }

    public String getOwnerUid() { return ownerUid; }
    public void setOwnerUid(String ownerUid) { this.ownerUid = ownerUid; }

    public String getRoutineId() { return routineId; }
    public void setRoutineId(String routineId) { this.routineId = routineId; }

    public long getTimestamp() { return timestamp; }
    public void setTimestamp(long timestamp) { this.timestamp = timestamp; }

    public String getOutcome() { return outcome; }
    public void setOutcome(String outcome) { this.outcome = outcome; }

    public String getTriggeringRule() { return triggeringRule; }
    public void setTriggeringRule(String triggeringRule) { this.triggeringRule = triggeringRule; }

    public String getExplanation() { return explanation; }
    public void setExplanation(String explanation) { this.explanation = explanation; }

    public String getUncertaintyReason() { return uncertaintyReason; }
    public void setUncertaintyReason(String uncertaintyReason) { this.uncertaintyReason = uncertaintyReason; }

    public List<SafetySignal> getSignals() { return signals != null ? signals : new ArrayList<>(); }
    public void setSignals(List<SafetySignal> signals) { this.signals = signals; }

    public boolean isDismissed() { return dismissed; }
    public void setDismissed(boolean dismissed) { this.dismissed = dismissed; }

    public String getActionTaken() { return actionTaken; }
    public void setActionTaken(String actionTaken) { this.actionTaken = actionTaken; }

    public boolean isDeduplicated() { return deduplicated; }
    public void setDeduplicated(boolean deduplicated) { this.deduplicated = deduplicated; }
}
